const seedTexts=[['v1','volunteer','【校园图书馆整理志愿者招募】\n活动时间：11月7日（周六）14:00—17:00\n地点：校图书馆一楼\n志愿时长：3小时\n面向：全校在校学生\n报名截止：11月3日20:00\n协助整理图书和引导读者。请在原群联系负责人报名。'],['r1','postgrad','【智能计算实验室招募本科研究助理】\n活动时间：每周可协商安排\n地点：信息楼 A305\n面向：计算机相关专业本科生，具备 Python 基础\n报名截止：11月6日18:00\n参与大模型应用评测与数据整理，需准备一页项目介绍。'],['l1','college','【从零到一：AI Agent 实践分享会】\n活动时间：11月5日（周四）19:00—20:30\n地点：学术交流中心 201\n面向：全校学生\n报名截止：11月4日18:00\n围绕工具调用、检索和评测展开，适合有 Python 基础的同学。'],['v2','volunteer','【周末社区科普志愿服务】\n活动时间：11月8日（周日）09:00—12:00\n地点：大学城社区服务中心\n志愿时长：3小时\n面向：愿意参与科学实验讲解的在校生\n报名截止：11月5日12:00\n带小朋友体验科学实验，交通需要自行安排。'],['c1','college','【校园应用创新竞赛开放报名】\n活动时间：11月21日作品展示\n地点：创新创业中心\n面向：在校本科生，可跨专业组队\n报名截止：11月10日18:00\n提交一个解决真实校园问题的应用原型和演示视频。']];
const digests=[{id:'d1',sourceId:'ai',category:'AI · 实践方法',title:'做 AI 应用，先建立一套小而真实的评测集',summary:'演示讨论围绕“原型能运行，却不知道好不好用”展开。建议从真实任务中选取样本，分别检查回答准确性、引用和失败情况，再比较不同方案。',why:'与你关注的「AI 应用开发」相关，可以直接用于正在构思的校园信息助手。',action:'今天可以做：整理 10 条真实需求，写出你期望的正确结果。',source:'AI 开发交流小组',evidence:'以下为虚构的演示讨论：\n甲：感觉模型输出挺好，但换一条输入就不稳定。\n乙：先固定十几个真实例子，给每个例子写验收标准。\n丙：还要测试没信息时是否会乱编，以及来源能不能对得上。',label:'群友经验 · 非官方结论'}, {id:'d2',sourceId:'postgrad',category:'保研 · 科研准备',title:'联系导师前，先用一页纸讲清自己的项目',summary:'这份演示分享建议用“问题、方法、自己的工作、结果、下一步”组织项目介绍。个人经历有参考价值，具体招生条件仍需要核对院系官方通知。',why:'与你关注的「科研机会」相关，适合为研究助理申请提前准备。',action:'今天可以做：选一个课程项目，整理一页项目介绍。',source:'保研经验分享群',evidence:'虚构经验分享：我会先说明想解决什么问题，再写自己完成的部分和结果。尽量保留代码、实验或演示作为证据。联系时间和材料要求以目标院系官方安排为准。',label:'个人经验 · 需核对官方要求'}, {id:'d3',sourceId:'tech',category:'科技阅读 · 信息筛选',title:'信息越多，越需要区分事实、观点和广告',summary:'这条手动导入示例强调：同一新闻的多次转发可以合并，但转述次数不能作为真实性依据。阅读摘要时，应保留原作者、时间与可核查的出处。',why:'与你关注的「高效获取科技信息」相关，有助于减少重复阅读。',action:'今天可以做：把一个高频来源设为“仅汇总”，降低打扰。',source:'科技与 AI 阅读清单',evidence:'本条为演示素材，并非真实公众号文章。系统目前没有读取任何订阅号。全文导入后，应保留原链接和抓取范围；只有标题时不能声称读过全文。',label:'演示文章 · 非真实公众号内容'}];
function fresh(){return {version:1,items:seedTexts.map(([id,source,raw],i)=>({...C.analyze(raw),id,sources:[source],saved:i===1,applied:false,ignored:false,reason:i===0?'符合「校内志愿」偏好，报名今晚截止':i===1?'与你的「计算机专业 · 科研准备」目标相关':i===2?'与你关注的「AI 应用开发」相关':'来自你关注的校园信息源'})),prefs:{types:Object.keys(C.TYPES),goal:'计算机专业 · 本科生',interests:'志愿服务、AI 应用开发、保研科研',instant:true,digestTime:'20:30'},enabled:[],sourcePolicyVersion:1,customSources:[],sourceModes:{},sourceSummaries:[],reminders:[],logs:[],feedback:{},savedDigests:[]};}
let state;try{const s=JSON.parse(localStorage.getItem('zhiyu-demo-v1'));state=s?.version===1&&Array.isArray(s.items)&&s.prefs&&Array.isArray(s.enabled)&&Array.isArray(s.reminders)&&Array.isArray(s.logs)&&Array.isArray(s.savedDigests)?s:fresh();}catch{state=fresh();}
ScopeCore.migrate(state,sources);
for(const source of state.customSources){if(source&&typeof source.id==='string'&&!sources.some(s=>s.id===source.id))sources.push(source);}
function allDigests(){return [...state.sourceSummaries,...digests];}
function selectedDigests(){return allDigests().filter(d=>ScopeCore.allows(state,sources,d.sourceId,'summary'));}
let page='today',filter='all',search='',libraryMode='all',toastTimer,previousFocus,lastResult=null,processing=false;
const persist=()=>{try{localStorage.setItem('zhiyu-demo-v1',JSON.stringify(state));}catch{toast('浏览器未允许本地存储；当前操作仅保留到页面关闭。');}};
const liveItems=()=>state.items.filter(x=>!x.ignored&&x.sources.some(s=>ScopeCore.allows(state,sources,s,'opportunities'))&&C.matches(x,state.prefs));
const actionable=()=>liveItems().filter(x=>x.status!=='cancelled'&&!x.applied);
const deadlineLabel=x=>{if(x.status==='cancelled')return '已取消 / 已满额';if(x.applied)return '已标记报名';const h=C.hoursUntil(x.deadline);return h===null?'截止时间待确认':h<0?'报名已截止':h<=8?`${Math.ceil(h)} 小时后截止`:`${dateText(x.deadline)} 截止`;};
function dateText(d){if(!d)return '待确认';return new Intl.DateTimeFormat('zh-CN',{timeZone:'Asia/Shanghai',month:'numeric',day:'numeric',hour:'2-digit',minute:'2-digit',hour12:false}).format(new Date(d));}
const sourceName=id=>sources.find(x=>x.id===id)?.name||'演示消息';
const typeIcon=t=>({volunteer:'heart',research:'flask',lecture:'mic',competition:'award'}[t]||'spark');
const button=(action,label,cl='',extra='')=>`<button class="btn ${cl}" data-action="${action}" ${extra}>${label}</button>`;
function toast(msg){clearTimeout(toastTimer);$('#toast').textContent=msg;$('#toast').hidden=false;toastTimer=setTimeout(()=>$('#toast').hidden=true,4300);}
function header(eye,title,subtitle,actions=''){return `<div class="page-heading"><div><div class="eyebrow">${eye}</div><h1>${title}</h1><p class="page-subtitle">${subtitle}</p></div><div class="heading-buttons">${actions}</div></div>`;}
function empty(text){return `<div class="empty">${icon('radar')}<p>${text}</p>${button('simulate','试试模拟一条消息','small')}</div>`;}
function filters(){return `<div class="filter-row" aria-label="机会类型筛选">${[['all','全部类型'],...Object.entries(C.TYPES)].map(([id,t])=>`<button class="filter ${filter===id?'active':''}" data-action="filter" data-value="${id}" aria-pressed="${filter===id}">${t}</button>`).join('')}</div>`;}
function card(x){const h=C.hoursUntil(x.deadline);return `<article class="opportunity"><div class="card-top"><span class="type-label ${x.type}">${icon(typeIcon(x.type))}${C.TYPES[x.type]}</span><span class="deadline ${x.status==='cancelled'?'cancelled':h!==null&&h<=8?'urgent':''}">${deadlineLabel(x)}</span></div><button class="card-title" data-action="detail" data-id="${esc(x.id)}">${esc(x.title)}</button><p class="card-description">${esc(x.summary.slice(0,78))}${x.summary.length>78?'…':''}</p><div class="meta-row"><span>${icon('clock')}${esc(x.eventTime)}</span><span>${icon('pin')}${esc(x.location)}</span>${x.type==='volunteer'?`<span>${icon('heart')}${esc(x.duration)}</span>`:''}</div><div class="match-line">${icon('spark')}${esc(x.reason||'匹配关注类型；时间与资格请核对原文')}${x.uncertain?' · 信息待补全':''}</div><div class="card-bottom"><div class="source-line"><span class="source-icon">${x.sources[0]==='ai'||x.sources[0]==='postgrad'?'Q':'微'}</span>${esc(sourceName(x.sources[0]))}${x.sources.length>1?` <span>+${x.sources.length-1} 个来源</span>`:''}<span>· 演示</span></div><div class="card-actions"><button class="save-btn ${x.saved?'saved':''}" data-action="save" data-id="${esc(x.id)}" aria-label="${x.saved?'取消收藏':'收藏'}${esc(x.title)}" aria-pressed="${!!x.saved}">${icon('book')}</button>${button('detail',`查看详情 ${icon('arrow')}`,'small',`data-id="${esc(x.id)}"`)}</div></div></article>`;}
function render(){
  $('#page-label').textContent=navs.find(x=>x[0]===page)?.[2]||'今日概览';
  $('#nav').innerHTML=navs.map(([id,i,t])=>`<button class="nav-item ${page===id?'active':''}" data-action="navigate" data-page="${id}" ${page===id?'aria-current="page"':''}>${icon(i)}<span>${t}</span>${id==='opportunities'?`<span class="nav-count">${actionable().length}</span>`:id==='library'?`<span class="nav-count">${state.items.filter(x=>x.saved).length+state.savedDigests.length}</span>`:''}</button>`).join('');
  $('#bell').innerHTML=icon('bell')+(state.reminders.length?'<i class="badge-dot"></i>':'');
  $('#main').innerHTML=({today:todayView,opportunities:opportunitiesView,digest:digestView,library:libraryView,sources:sourcesView,settings:settingsView}[page]||todayView)();
}
function todayView(){const items=actionable(),urgent=items.filter(x=>C.hoursUntil(x.deadline)!==null&&C.hoursUntil(x.deadline)>=0&&C.hoursUntil(x.deadline)<=24);return header('YOUR PERSONAL SIGNAL','同学，下午好。','重要的机会和值得读的内容，已经为你整理好了。',button('navigate','管理关注','secondary-heading','data-page="settings"')+button('simulate',icon('plus')+'导入消息','primary'))+`<section class="hero"><div><div class="eyebrow">LESS NOISE. MORE POSSIBILITY.</div><h2>把重要的事，留给你。</h2><p>不必追赶每一条消息。让值得行动的机会，<br>和真正有用的知识，主动来到你身边。</p><button class="hero-link" data-action="navigate" data-page="opportunities">今天有 ${items.length} 个机会值得关注 ${icon('arrow')}</button></div><div class="radar-art" aria-hidden="true"><div class="orbit three"></div><div class="orbit"></div><div class="orbit two"></div><div class="radar-core">${icon('radar')}</div><span class="float-chip a">${icon('check')} 找到相关机会</span><span class="float-chip b">✦ 已过滤重复消息</span><span class="little-star">✧</span></div></section><section class="stats" aria-label="演示数据概览">${[[items.length,'待关注机会','radar','<strong>'+urgent.length+' 个</strong> 将在 24 小时内截止',''],[urgent.length,'近期截止','clock','及时发现，不错过每一次可能','orange'],[digests.length,'今日精选','spark','按你的目标，留下值得读的','blue'],[state.enabled.length,'关注信息源','source','全部为模拟来源，未连接账号','purple']].map(([n,t,i,d,cl])=>`<div class="stat ${cl}"><div class="stat-top">${t}<span class="stat-icon">${icon(i)}</span></div><div class="stat-value">${n}<small>${t==='关注信息源'?'个来源':'条信息'}</small></div><div class="stat-bottom">${d}</div></div>`).join('')}</section><div class="dashboard-grid"><div><div class="section-heading"><h2>你的机会雷达<small>先看与你有关的</small></h2>${button('navigate','查看全部 ↗','text','data-page="opportunities"')}</div>${filters()}${items.filter(x=>filter==='all'||x.type===filter).slice(0,3).map(card).join('')||empty('当前筛选下没有待关注机会。')}<section class="brief-preview"><div class="section-heading"><h2>值得读的三件事</h2><span class="live-pill">✦ 每日精选</span></div>${digests.slice(0,2).map((d,i)=>`<button class="brief-item" style="width:100%;text-align:left" data-action="digest-detail" data-id="${d.id}"><span class="brief-number">0${i+1}</span><span><strong>${esc(d.title)}</strong><p>${esc(d.source)} · ${esc(d.label)}</p></span><span class="tag">${d.category.split(' · ')[0]}</span></button>`).join('')}${button('navigate','打开今日简报 '+icon('arrow'),'text','data-page="digest"')}</section><div class="demo-banner">${icon('info')}演示时钟固定为 2026 年 11 月 3 日 16:00，所有消息均为虚构。</div></div><aside class="right-rail">${rightRail(urgent)}</aside></div>`;}
function rightRail(urgent){return `<section class="side-panel"><h3>留意这些时间</h3><p class="panel-sub">2026 年 11 月 · 演示日历</p><div class="calendar-days">${['一','二','三','四','五','六','日'].map((d,i)=>`<div class="${i===1?'selected':''}"><small>${d}</small>${i+2}</div>`).join('')}</div>${urgent.slice(0,2).map(x=>`<button class="upcoming" style="text-align:left" data-action="detail" data-id="${x.id}"><span class="time-mark">${dateText(x.deadline).split(' ').pop()}<small>报名截止</small></span><span><strong>${esc(x.title)}</strong><p>点击查看详情与原文</p></span></button>`).join('')||'<p class="panel-sub" style="margin-top:15px">24 小时内没有已知截止事项</p>'}<div class="panel-divider"></div><button class="btn text" style="font-size:10px" data-action="notifications">查看我的提醒 (${state.reminders.length}) →</button></section><section class="side-panel"><div class="section-heading" style="margin:0"><h3>我的关注方向</h3><button class="icon-button" data-action="navigate" data-page="settings" aria-label="编辑关注方向">${icon('settings')}</button></div><p class="panel-sub">${esc(state.prefs.goal)}</p><div class="tags">${state.prefs.interests.split(/[、,，]/).filter(Boolean).map(t=>`<span class="tag">${esc(t)}</span>`).join('')}</div><p class="panel-sub" style="margin-top:15px">只保留与你当前目标相关的信息。</p></section><section class="side-panel"><h3>信息从哪里来</h3><p class="panel-sub">演示中启用 ${state.enabled.length} 个来源</p>${sources.filter(s=>state.enabled.includes(s.id)).slice(0,3).map(s=>`<div class="source-mini"><span class="source-icon">${s.glyph}</span><span>${s.name}<small>${s.platform}</small></span><span>模拟</span></div>`).join('')}${button('navigate','管理信息来源 →','text','data-page="sources"')}</section>`;}
function opportunitiesView(){const all=liveItems().filter(x=>(filter==='all'||x.type===filter)&&(!search||[x.title,x.summary,x.location,...x.sources.map(sourceName)].join(' ').toLowerCase().includes(search.toLowerCase())));return header('OPPORTUNITY RADAR','不错过，下一次可能。','匹配你的关注方向，保留原文，帮你判断是否值得行动。',button('simulate',icon('plus')+'导入消息','primary'))+`<label class="search-bar">${icon('search')}<input id="search" type="search" value="${esc(search)}" placeholder="搜索活动、地点、关键词或来源…" aria-label="搜索机会"></label>${filters()}<div class="section-heading"><span class="small-label">找到 ${all.length} 条机会 · 包含已报名或已取消的信息</span></div><div class="full-grid">${all.map(card).join('')||empty('没有匹配的机会，试试其他关键词或关注类型。')}</div>`;}
function digestCard(d,i){return `<article class="digest-card"><span class="digest-index">0${i+1}</span><div style="flex:1;min-width:0"><span class="category">${esc(d.category)}</span><h3>${esc(d.title)}</h3><p>${esc(d.summary)}</p><div class="why">✦ ${esc(d.why)}</div><div class="digest-footer"><span>${esc(d.source)} · ${esc(d.label)}</span>${button('digest-detail','展开阅读 ↗','small',`data-id="${d.id}"`)}</div><div class="feedback" aria-label="精选反馈">${[['useful','有用'],['basic','太基础'],['irrelevant','不相关']].map(([v,t])=>`<button class="${state.feedback[d.id]===v?'active':''}" data-action="feedback" data-id="${d.id}" data-value="${v}" aria-pressed="${state.feedback[d.id]===v}">${t}</button>`).join('')}</div></div></article>`;}
function digestView(){return header('DAILY BRIEF','每天五分钟，遇见好信息。','去掉重复与闲聊，把注意力留给与你有关的内容。',button('export-digest',icon('download')+'导出简报'))+`<div class="digest-main"><section class="digest-cover"><span class="eyebrow">THE SIFT DAILY / 示例简报</span><h2>把信息看少一点，<br>把收获留下多一点。</h2><p>11 月 3 日 · 3 条精选 · 约 3 分钟阅读</p><span class="edition">No. 001</span></section><div class="notice-box">这是一份<strong>预先编写的示例简报</strong>，用来体验呈现方式。反馈会保存在当前浏览器；尚未接入实时群聊或大模型，也不会自动生成日报。</div><div class="digest-list">${digests.map(digestCard).join('')}</div></div>`;}
function libraryView(){const items=state.items.filter(x=>x.saved),ds=allDigests().filter(x=>state.savedDigests.includes(x.id));return header('YOUR COLLECTION','有用的，留在这里。','机会和知识都可以收藏，在需要时重新找到。',button('export',icon('download')+'导出演示数据'))+`<div class="view-options">${[['all','全部收藏'],['opportunities','机会'],['digests','精选文章']].map(([v,t])=>`<button class="filter ${libraryMode===v?'active':''}" data-action="library-filter" data-value="${v}">${t}</button>`).join('')}</div><div class="full-grid">${libraryMode!=='digests'?items.map(card).join(''):''}</div><div class="digest-list" style="margin-top:16px">${libraryMode!=='opportunities'?ds.map(digestCard).join(''):''}</div>${((libraryMode==='all'&&!items.length&&!ds.length)||(libraryMode==='opportunities'&&!items.length)||(libraryMode==='digests'&&!ds.length))?empty('还没有收藏。打开机会或精选详情，点击收藏即可。'):''}`;}
function sourcesView(){return header('YOUR INFORMATION SOURCES','信息有来处，判断有依据。','为每个来源设置关注范围，避免把无关聊天变成新的噪音。',button('simulate','测试模拟采集','primary'))+`<div class="notice-box"><strong>当前没有连接任何微信、QQ 或公众号账号。</strong> 下方开关只控制演示消息能否进入机会雷达。真实接入需要单独开发和验证；安卓通知监听也无法保证覆盖免打扰群、图片和完整聊天记录。</div><div class="full-grid">${sources.map(s=>`<article class="source-card"><div class="source-card-top"><span class="source-logo ${s.kind}">${s.glyph}</span><div><h3>${s.name}</h3><span class="sub">${s.platform}</span></div><button class="switch ${state.enabled.includes(s.id)?'on':''}" role="switch" aria-checked="${state.enabled.includes(s.id)}" aria-label="启用${s.name}演示来源" data-action="source-toggle" data-id="${s.id}"></button></div><p class="source-info">${s.desc}<br>接入状态：未接入 · 当前使用虚构消息</p><div class="source-state"><span>${state.enabled.includes(s.id)?'● 演示来源已启用':'○ 演示来源已暂停'}</span><span>本地处理 · 可随时关闭</span></div></article>`).join('')}</div><section class="message-log"><h3 style="font-size:13px">最近的演示处理记录</h3>${state.logs.length?state.logs.slice(0,8).map(l=>`<div class="log-entry"><time>${esc(l.time)}</time><div><strong>${esc(l.title)}</strong><p>${esc(l.detail)}</p></div></div>`).join(''):'<p class="panel-sub">还没有记录。点击「测试模拟采集」，试着发送一条消息。</p>'}</section>`;}
function settingsView(){return header('MAKE IT YOURS','你关心的，才是重要的。','告诉Sift你的目标，决定哪些内容值得打扰。')+`<div class="digest-main"><form id="prefs-form"><section class="setting-box"><h3>我的关注画像</h3><p class="sub">类型筛选会立即影响机会雷达；自由填写的目标和兴趣仅展示，尚未参与语义匹配。</p><div class="field-grid"><label class="field">身份与阶段<input name="goal" maxlength="60" value="${esc(state.prefs.goal)}" required></label><label class="field">兴趣方向<input name="interests" maxlength="120" value="${esc(state.prefs.interests)}" placeholder="用顿号或逗号分隔"></label></div><label class="field">希望发现的机会</label><div class="checkboxes">${Object.entries(C.TYPES).map(([v,t])=>`<label><input name="types" type="checkbox" value="${v}" ${state.prefs.types.includes(v)?'checked':''}>${t}</label>`).join('')}</div></section><section class="setting-box"><h3>提醒偏好</h3><div class="setting-row"><span><p>新机会即时提示</p><small>仅在本页面模拟消息时弹出提示；不是系统推送</small></span><label><input type="checkbox" name="instant" ${state.prefs.instant?'checked':''} aria-label="新机会即时提示"></label></div><label class="field">每日简报时间<input type="time" name="digestTime" value="${esc(state.prefs.digestTime)}" required></label><p class="sub" style="margin-top:8px">此设置仅保存偏好，网页关闭后不会定时生成或发送简报。</p></section><button class="btn primary" type="submit">保存关注设置 ${icon('check')}</button></form><section class="setting-box" style="margin-top:24px"><h3>数据与演示</h3><p class="sub">交互数据只保存在当前浏览器，不跨设备同步。输入消息由本地规则解析，不发送给模型。</p><div class="setting-row"><span><p>导出当前数据</p><small>JSON 格式，包含你输入的内容与演示设置</small></span>${button('export','导出','small')}</div><div class="setting-row"><span><p>恢复初始演示</p><small>清除本浏览器中的操作记录和输入，恢复示例</small></span>${button('reset-confirm','重置','small danger')}</div></section></div>`;}
function showModal(html){previousFocus=document.activeElement;$('#modal-content').innerHTML=html;$('#modal').hidden=false;document.body.style.overflow='hidden';$('#modal .modal-close').focus();}
function closeModal(){$('#modal').hidden=true;document.body.style.overflow='';previousFocus?.isConnected&&previousFocus.focus();}
function showDetail(id){const x=state.items.find(x=>x.id===id);if(!x)return;showModal(`<span class="type-label ${x.type}">${icon(typeIcon(x.type))}${C.TYPES[x.type]} · 演示信息</span><h2 id="modal-title">${esc(x.title)}</h2><p class="modal-description">${esc(x.reason||'按机会类型匹配，资格与时间请核对原文。')}</p><div class="detail-fields">${[['活动时间',x.eventTime],['报名截止',x.deadline?dateText(x.deadline):'待确认：未提供明确日期与时间'],['活动地点',x.location],['志愿时长',x.duration],['参与条件',x.eligibility],['当前状态',x.status==='cancelled'?'已取消 / 已满额':x.applied?'已标记报名':'待关注']].map(([t,v])=>`<div class="detail-field"><small>${t}</small><span>${esc(v)}</span></div>`).join('')}</div><section class="evidence"><h3>原始消息 · 信息核对</h3><p class="panel-sub">${x.sources.map(sourceName).map(esc).join(' / ')} · 虚构来源</p><pre>${esc(x.raw)}</pre></section>${x.history?.length?`<details class="history"><summary>查看变更前消息（${x.history.length} 条）</summary>${x.history.map(h=>`<pre style="white-space:pre-wrap">${esc(h.raw)}</pre>`).join('')}</details>`:''}<div class="modal-actions">${button('save',icon('book')+(x.saved?'已收藏 · 点击取消':'收藏机会'),'primary',`data-id="${x.id}"`)}${x.status!=='cancelled'?button('apply',x.applied?'取消报名标记':'标记已报名','',`data-id="${x.id}"`)+button('remind',icon('bell')+'设置提醒','',`data-id="${x.id}"`):''}${button('ignore','不再关注','',`data-id="${x.id}"`)}</div><p class="panel-sub" style="margin-top:13px">“标记已报名”只记录状态，不会提交报名。提醒仅为演示记录，不会实际推送。</p>`);}
function showDigest(id){const d=allDigests().find(x=>x.id===id);if(!d)return;showModal(`<span class="eyebrow">${esc(d.category)}</span><h2 id="modal-title">${esc(d.title)}</h2><p class="modal-description">${esc(d.summary)}</p><div class="analysis-result"><h3>与你的关系</h3>${esc(d.why)}<br><strong>${esc(d.action)}</strong></div><section class="evidence"><h3>来源片段 · ${esc(d.label)}</h3><p class="panel-sub">${esc(d.source)}</p><pre>${esc(d.evidence)}</pre></section><div class="modal-actions">${button('save-digest',icon('book')+(state.savedDigests.includes(id)?'已收藏 · 点击取消':'收藏这条精选'),'primary',`data-id="${id}"`)}${button('close','读完了')}</div>`);}
const samples=[{id:'new',name:'一条新的志愿招募',hint:'发现机会 → 提取时间与地点',symbol:'＋',source:'volunteer',raw:'【校园开放日志愿讲解员招募】\n活动时间：11月7日（周六）09:00—12:00\n地点：校内综合楼\n志愿时长：3小时\n面向：全校在校学生\n报名截止：11月4日12:00\n协助来访学生了解校园，需提前参加培训。'}, {id:'duplicate',name:'同一活动被转发到另一个群',hint:'跨群去重 → 合并来源，不重复建卡',symbol:'⇄',source:'college',raw:seedTexts[0][2]}, {id:'update',name:'活动名额已满',hint:'更新状态 → 停止该活动报名提醒',symbol:'↻',source:'volunteer',raw:'【校园图书馆整理志愿者招募】更新：名额已满，报名结束。活动时间：11月7日14:00—17:00\n地点：校图书馆一楼\n志愿时长：3小时\n面向：全校在校学生\n报名截止：11月3日20:00'}, {id:'noise',name:'群里的一句闲聊',hint:'过滤无关内容 → 不触发提醒',symbol:'☁',source:'ai',raw:'大家今晚吃什么？食堂二楼今天还开吗？'}, {id:'uncertain',name:'信息不完整的活动',hint:'保留未知字段 → 提醒核对，不编造',symbol:'?',source:'volunteer',raw:'【周末环保志愿活动】本周末有环保志愿活动，具体时间地点稍后通知，有兴趣的同学先关注一下。'}];
function simulation(){lastResult=null;showModal(`<span class="eyebrow">MESSAGE PLAYGROUND</span><h2 id="modal-title">让一条消息，变成一次机会。</h2><p class="modal-description">选择一个情景，或输入自己的示例。使用浏览器本地规则解析，无大模型调用，不读取任何真实聊天。</p><div class="pipeline"><span id="step-1">01 接收消息</span><b>→</b><span id="step-2">02 提取与去重</span><b>→</b><span id="step-3">03 匹配关注</span><b>→</b><span id="step-4">04 生成结果</span></div><div class="sample-list">${samples.map(s=>`<button class="sample-btn" data-action="sample" data-id="${s.id}"><span>${s.symbol}</span><span><strong>${s.name}</strong><small>${s.hint}</small></span><span>↗</span></button>`).join('')}</div><details style="margin-top:19px"><summary class="small-label" style="cursor:pointer">或粘贴一条自己的示例消息</summary><form id="message-form"><label class="field">演示来源<select name="source">${sources.map(s=>`<option value="${s.id}">${s.name}${state.enabled.includes(s.id)?'':'（已暂停）'}</option>`).join('')}</select></label><label class="field">消息内容<textarea name="message" maxlength="4000" required placeholder="【活动名称】&#10;活动时间：11月7日14:00—17:00&#10;地点：校图书馆&#10;志愿时长：3小时&#10;报名截止：11月4日12:00"></textarea></label><p class="panel-sub">演示规则支持明确的“11月4日12:00”；缺少年份按演示年 2026 处理。相对日期和语义条件暂不解析。</p><button type="submit" class="btn primary" style="margin-top:12px">分析这条消息</button></form></details><div id="simulation-result" aria-live="polite"></div>`);}
async function processMessage(source,raw){
  if(processing)return;
  const target=$('#simulation-result');
  // Check the whitelist before calling any analyzer or retaining message text.
  const result=ScopeCore.process(state,sources,source,raw,C.analyze);
  if(result.kind==='blocked'){target.innerHTML='<div class="analysis-result"><h3>来源未选择，已跳过分析</h3><p>请先在信息来源中选择这个群或公众号。消息正文没有保存。</p></div>';return;}
  if(result.kind==='empty'){target.innerHTML='<div class="analysis-result">请先输入消息。</div>';return;}
  processing=true;document.querySelectorAll('.sample-btn,#message-form button').forEach(b=>b.disabled=true);
  try{
    let itemId,title='内容摘要已保存',detail='按原文前四个非空段落去重摘录；可在「摘要」中查看并核对原文。';
    if(result.summary&&!state.sourceSummaries.some(d=>d.sourceId===source&&d.evidence===result.summary.evidence)){
      state.sourceSummaries.unshift({...result.summary,id:crypto.randomUUID(),sourceId:source,source:sourceName(source),category:'本地摘录',why:'来自你指定的信息源；此处只做原文摘录，不进行价值判断。',action:'查看原文，核对具体要求。',label:'手动导入 · 规则摘录'});
    }
    const parsed=result.opportunity;
    if(parsed?.kind==='noise'||parsed?.kind==='empty'){
      title=result.summary?'已生成原文摘录，未发现机会':'未发现匹配的机会';detail=result.summary?detail:parsed.reason;
    }else if(parsed){
      const item={...parsed,id:crypto.randomUUID(),sources:[source],saved:false,applied:false,ignored:false,reason:'来自你指定的信息源；本地规则识别，请核对原文。'};
      const ingested=C.ingest(state.items,item);state.items=ingested.items;itemId=ingested.item.id;
      if(ingested.kind==='updated'&&ingested.item.status==='cancelled')state.reminders=state.reminders.filter(r=>r.itemId!==itemId);
      title=ingested.kind==='duplicate'?'重复机会已合并':ingested.kind==='updated'?'活动状态已更新':'发现一条新的'+C.TYPES[item.type];
      detail=(!C.matches(item,state.prefs)?'该类型未在关注范围中，不显示在机会列表。':'已提取机会信息，请核对时间、地点和参与条件。')+(result.summary?' 原文摘录已存入「摘要」。':'');
      if(state.prefs.instant&&ingested.kind==='created'&&C.matches(item,state.prefs))toast('发现新机会：'+item.title);
    }
    state.logs.unshift({time:new Date().toLocaleTimeString('zh-CN'),title,detail});state.logs=state.logs.slice(0,30);
    persist();render();lastResult=itemId;
    target.innerHTML=`<div class="analysis-result"><h3>${esc(title)}</h3><p>${esc(detail)}</p>${itemId?button('detail','查看机会','small',`data-id="${itemId}"`):button('navigate','查看摘要','small','data-page="digest"')}</div>`;
  }finally{processing=false;document.querySelectorAll('.sample-btn,#message-form button').forEach(b=>b.disabled=false);}
}
function remindersModal(){showModal(`<span class="eyebrow">YOUR REMINDERS</span><h2 id="modal-title">给重要的事，留个位置。</h2><p class="modal-description">以下仅为提醒计划的交互演示。没有系统推送、后台定时任务或日历写入。</p>${state.reminders.length?state.reminders.map(r=>`<div class="reminder-item">${icon('bell')}<span><strong>${esc(state.items.find(x=>x.id===r.itemId)?.title||'已删除活动')}</strong><small>${esc(r.label)} · 待处理</small></span>${button('remove-reminder','移除','small',`data-id="${r.id}"`)}</div>`).join(''):'<div class="empty" style="margin-top:20px"><p>还没有提醒。打开机会详情，设置一条提醒。</p></div>'}`);}
function download(name,content,type){const a=document.createElement('a'),url=URL.createObjectURL(new Blob([content],{type}));a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
document.addEventListener('click',e=>{const b=e.target.closest('[data-action]');if(!b||b.disabled)return;const {action,id,value}=b.dataset;const x=state.items.find(x=>x.id===id);switch(action){case'navigate':page=b.dataset.page;filter='all';search='';closeModal();render();window.scrollTo({top:0,behavior:'instant'});break;case'filter':filter=value;render();break;case'library-filter':libraryMode=value;render();break;case'detail':showDetail(id);break;case'digest-detail':showDigest(id);break;case'close':if(!processing)closeModal();break;case'save':if(x){x.saved=!x.saved;persist();render();if(!$('#modal').hidden)showDetail(id);toast(x.saved?'已加入我的收藏':'已取消收藏');}break;case'apply':if(x){x.applied=!x.applied;if(x.applied)state.reminders=state.reminders.filter(r=>r.itemId!==id);persist();render();showDetail(id);toast(x.applied?'已标记报名；不会替你实际报名':'已取消报名标记');}break;case'ignore':if(x){x.ignored=true;state.reminders=state.reminders.filter(r=>r.itemId!==id);persist();closeModal();render();toast('已从机会雷达隐藏，收藏仍可保留');}break;case'remind':if(x)showModal(`<span class="eyebrow">SET A REMINDER</span><h2 id="modal-title">稍后，再提醒自己。</h2><p class="modal-description">${esc(x.title)}<br>仅保存演示计划，不实际发送通知。</p><div class="sample-list">${[['30','演示时钟 30 分钟后','11 月 3 日 16:30'],['120','演示时钟 2 小时后','11 月 3 日 18:00']].map(([v,t,d])=>`<button class="sample-btn" data-action="set-reminder" data-id="${id}" data-value="${v}"><span>◷</span><span><strong>${t}</strong><small>${d}</small></span><span>→</span></button>`).join('')}</div>`);break;case'set-reminder':state.reminders=state.reminders.filter(r=>r.itemId!==id);state.reminders.push({id:crypto.randomUUID(),itemId:id,label:dateText(new Date(C.BASE+Number(value)*60000).toISOString())+'（演示）'});persist();render();remindersModal();toast('演示提醒已保存，不会实际推送');break;case'notifications':remindersModal();break;case'remove-reminder':state.reminders=state.reminders.filter(r=>r.id!==id);persist();render();remindersModal();break;case'source-toggle':state.enabled=state.enabled.includes(id)?state.enabled.filter(s=>s!==id):[...state.enabled,id];persist();render();break;case'simulate':simulation();break;case'sample':{const s=samples.find(x=>x.id===id);if(s)processMessage(s.source,s.raw);}break;case'save-digest':state.savedDigests=state.savedDigests.includes(id)?state.savedDigests.filter(s=>s!==id):[...state.savedDigests,id];persist();render();showDigest(id);toast(state.savedDigests.includes(id)?'已收藏这条精选':'已取消收藏');break;case'feedback':state.feedback[id]=value;persist();render();toast('反馈已保存在本浏览器；尚未接入推荐模型');break;case'export':download('sift-demo-data.json',JSON.stringify(state,null,2),'application/json');toast('已导出演示数据');break;case'export-digest':download('Sift-2026-11-03-示例简报.md','# Sift · 每日精选（虚构演示）\n\n'+selectedDigests().map(d=>`## ${esc(d.title)}\n\n${esc(d.summary)}\n\n${esc(d.why)}\n\n${esc(d.action)}\n\n来源：${esc(d.source)}（${esc(d.label)}）`).join('\n\n'),'text/markdown;charset=utf-8');break;case'reset-confirm':showModal(`<h2 id="modal-title">恢复初始演示？</h2><p class="modal-description">将删除当前浏览器中的输入消息、收藏、提醒和偏好，恢复初始示例。</p><div class="modal-actions">${button('reset','确认重置','danger')}${button('close','保留当前数据')}</div>`);break;case'reset':state=fresh();persist();closeModal();filter='all';render();toast('已恢复初始演示');break;case'about':showModal(`<span class="eyebrow">ABOUT SIFT</span><h2 id="modal-title">Sift · 校园信息雷达</h2><p class="modal-description">一个面向大学生的交互原型，探索“机会发现 → 原文核对 → 行动提醒 → 知识收藏”的流程。</p><div class="notice-box" style="margin-top:20px">已实现：本地规则解析、机会筛选、重复合并、状态更新、收藏、提醒计划、偏好保存与数据导出。<br><br>未实现：微信 / QQ 真实消息采集、公众号自动订阅、大模型分析、后台推送与跨设备同步。</div><p class="modal-description">所有初始内容均为虚构。演示时钟固定在 2026 年 11 月 3 日 16:00。输入内容仅保存在本浏览器，建议使用测试消息。</p>`);break;}});
document.addEventListener('submit',e=>{if(e.target.id==='prefs-form'){e.preventDefault();const fd=new FormData(e.target),types=fd.getAll('types');state.prefs={...state.prefs,goal:fd.get('goal').trim(),interests:fd.get('interests').trim(),types,instant:fd.has('instant'),digestTime:fd.get('digestTime')};persist();render();toast('关注设置已保存，机会类型筛选已更新');}if(e.target.id==='message-form'){e.preventDefault();const fd=new FormData(e.target);processMessage(fd.get('source'),fd.get('message'));}});
document.addEventListener('input',e=>{if(e.target.id==='search'){const position=e.target.selectionStart;search=e.target.value;render();const input=$('#search');input.focus();try{input.setSelectionRange(position,position);}catch{}}});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')&&!processing)closeModal();});
document.addEventListener('keydown',e=>{if($('#modal').hidden)return;if(e.key==='Escape'&&!processing)closeModal();if(e.key==='Tab'){const f=[...$('#modal').querySelectorAll('button:not(:disabled),a[href],input,select,textarea,summary')].filter(x=>x.getClientRects().length),first=f[0],last=f[f.length-1];if(e.shiftKey&&document.activeElement===first){e.preventDefault();last.focus();}else if(!e.shiftKey&&document.activeElement===last){e.preventDefault();first.focus();}}});
window.addEventListener('hashchange',()=>{const n=location.hash.slice(1);if(navs.some(x=>x[0]===n)){page=n;render();}});
if(navs.some(x=>x[0]===location.hash.slice(1)))page=location.hash.slice(1);
render();
